const body = $input.first().json.body || $input.first().json;
const day = body.follow_up_day || 1;
const name = (body.lead_name || '').split(' ')[0] || 'there';
const biz = body.business_name || 'ELION';
const msgs = {
  1: 'Hi ' + name + ',

Just checking in on your enquiry to ' + biz + '. Have you had a chance to review what we discussed?

We are here to help whenever you are ready.

Best regards,
' + biz,
  3: 'Hi ' + name + ',

Following up again regarding ' + biz + '. We noticed you have not yet moved forward and wanted to make sure you have everything you need.

Would you like to schedule a quick call?

Best regards,
' + biz,
  7: 'Hi ' + name + ',

This is your final follow-up from ' + biz + '. We understand timing is everything and we will not contact you further unless you reach out.

If you need us in the future, we are here.

Best regards,
' + biz
};
const message = msgs[day] || msgs[1];
return [{ json: { lead_email: body.lead_email, lead_name: body.lead_name, business_name: biz, message, follow_up_day: day } }];
